input.command:
cd /tmp
C=/tmp/c2.txt; B="http://maker:4000"
# find current reference tag id from the wikipedia item
REFID=$(curl -sS -c $C -b $C --max-time 20 "$B/api/bookmarks" | python3 -c 'import sys,json;d=json.load(sys.stdin);
for i in d["items"]:
  for t in i["tags"]:
    if t["name"]=="reference": print(t["id"])')
echo "reference tag id: $REFID"
echo "--- filter by that id ---"
curl -sS -c $C -b $C --max-time 20 "$B/api/bookmarks?tagId=$REFID" | python3 -c 'import sys,json;d=json.load(sys.stdin);[print(" ",i["title"],[t["name"] for t in i["tags"]]) for i in d["items"]];print("  total",d["total"])'
# also check if a tags list endpoint exists
echo "--- /api/tags ---"
curl -sS -c $C -b $C --max-time 20 "$B/api/tags" -w "\nHTTP %{http_code}\n" | head -5

